type Counts = { Files: number; Types: number; Instantiations: number };

function readCounts(output: string): Counts {
  const read = (name: keyof Counts): number => {
    const match = new RegExp(`^${name}:\\s+(\\d+)$`, "m").exec(output);
    if (!match) throw new Error(`no ${name} line`);
    return Number(match[1]);
  };
  return { Files: read("Files"), Types: read("Types"), Instantiations: read("Instantiations") };
}

function compare(before: Counts, after: Counts): void {
  for (const key of ["Files", "Types", "Instantiations"] as const) {
    const change = Math.round(((after[key] - before[key]) / before[key]) * 100);
    console.log(`${key}: ${change >= 0 ? "+" : ""}${change}%`);
  }
}

const before = readCounts("Files: 297\nTypes: 3779\nInstantiations: 3954\nCheck time: 0.042s");
const after = readCounts("Files: 297\nTypes: 4232\nInstantiations: 5931\nCheck time: 0.061s");
compare(before, after);

