function listPaths(value: unknown, maxDepth: number, prefix = ""): string[] {
  if (maxDepth === 0 || typeof value !== "object" || value === null) return [];
  const paths: string[] = [];
  for (const [key, child] of Object.entries(value)) {
    const path = prefix ? `${prefix}.${key}` : key;
    paths.push(path, ...listPaths(child, maxDepth - 1, path));
  }
  return paths;
}

const settings = {
