type Result = { file: string; types: number };

function checkBudgets(results: Result[], budgets: Record<string, number>): number {
  let failures = 0;
  for (const { file, types } of results) {
    const budget = budgets[file];
    if (budget === undefined) {
      console.log(`NO BUDGET ${file} (${types} types)`);
      failures++;
    } else if (types > budget) {
      console.log(`OVER ${file}: ${types} types, budget ${budget}`);
      failures++;
    } else {
      console.log(`OK ${file}: ${types} types, budget ${budget}`);
    }
  }
  return failures;
}

const failures = checkBudgets(
  [
    { file: "paths-full.ts", types: 6100 },
    { file: "paths-capped.ts", types: 870 },
    { file: "routes.ts", types: 1200 },
  ],
  { "paths-full.ts": 3000, "paths-capped.ts": 3000 },
);
console.log("failures:", failures);

